   1 /**
   2  * Guards the contract between the `expert-review` agent, which returns a scored plan
   3  * review, and `pipeline.md`, which records a panel of them as per-reviewer verdicts.
   4  *
   5  * The reason this guard exists: the agent repeatedly returned confident reviews built on
   6  * file contents it had never read, reporting no tool use, and its own prose prohibition
   7  * against doing so did not stop it. The fix is not a stronger instruction — it is a
   8  * declared `grounding` field the parent can screen, and a parent that discards rather
   9  * than averages a review that fails the screen. Both halves have to stay in place for
  10  * either to be worth anything, and they live in two prompt files with no import between
  11  * them, so nothing but a test relates them.
  12  *
  13  * Three properties are load-bearing:
  14  *
  15  * 1. The field list the agent emits matches the one the pipeline says it receives. The
  16  *    field names are parsed from the agent's own output table rather than hardcoded, so
  17  *    renaming one fails here instead of silently dropping from the screen.
  18  * 2. The pipeline states the discard rule and every condition that triggers it. A
  19  *    condition quietly deleted turns the screen back into an average-everything step.
  20  * 3. The pipeline refuses to present a shrunken panel as a consensus. Two of five
  21  *    reviewers failing is the observed case, and reporting the survivor's score as a
  22  *    panel aggregate is how that becomes invisible.
  23  *
  24  * What this CANNOT prove: that the screen runs, or that a reviewer declares its grounding
  25  * honestly — a fabricated `grounding` entry is still possible and is exactly why the
  26  * pipeline also screens for the no-tool-use contradiction rather than trusting the field
  27  * alone. CI sees text in a file, nothing more.
  28  */
  29 import { readFile } from "node:fs/promises";
  30 import { join } from "node:path";
  31 
  32 import { describe, expect, test } from "bun:test";
  33 
  34 const actionDir = join(import.meta.dirname, "..");
  35 const repoRoot = join(actionDir, "..", "..", "..");
  36 const autopilotDir = join(repoRoot, "claude-plugins/autopilot");
  37 
  38 const [agent, pipeline, chapter] = await Promise.all([
  39   readFile(join(autopilotDir, "agents/expert-review.md"), "utf8"),
  40   readFile(join(autopilotDir, "skills/plan/references/pipeline.md"), "utf8"),
  41   readFile(join(repoRoot, "docs/05-plan-run-skills.md"), "utf8"),
  42 ]);
  43 
  44 /**
  45  * The `| \`field\` |` rows of the agent's Phase 4 output table, sliced to that section so
  46  * the five-dimension rubric table above it does not leak in.
  47  */
  48 function outputFields(source: string): string[] {
  49   const section = source.split("## Phase 4: Output")[1]?.split("Example (illustrative")[0] ?? "";
  50   return [...section.matchAll(/^\|\s*`(\w+)`/gm)].map((row) => row[1]);
  51 }
  52 
  53 /** The backticked names on the pipeline's "Each returns JSON (…)" line. */
  54 function pipelineFields(source: string): string[] {
  55   const line = source.split("\n").find((l) => l.startsWith("Each returns JSON ("));
  56   return [...(line ?? "").matchAll(/`(\w+)`/g)].map((m) => m[1]);
  57 }
  58 
  59 /**
  60  * Top-level keys of the `expert-review` payload sketch in chapter 5's sub-agent contract
  61  * list — a third copy of the same contract, and the one that already drifted once.
  62  * Nested keys inside `dimensions{…}` are stripped so only the outer shape is compared.
  63  */
  64 function chapterFields(source: string): string[] {
  65   const line = source.split("\n").find((l) => l.startsWith("- `expert-review` →"));
  66   const body = (line ?? "").replace(/(\w)\{[^{}]*\}/g, "$1");
  67   return [...body.matchAll(/[{,]\s*(\w+)/g)].map((m) => m[1]);
  68 }
  69 
  70 const declared = outputFields(agent);
  71 
  72 describe("expert review contract", () => {
  73   test("the agent's output table is parseable and non-trivial", () => {
  74     expect(declared.length).toBeGreaterThan(4);
  75     expect(declared).toContain("findings");
  76   });
  77 
  78   test("the agent declares a grounding field", () => {
  79     expect(declared).toContain("grounding");
  80   });
  81 
  82   test("grounding is required, not optional", () => {
  83     const row = agent.split("\n").find((l) => /^\|\s*`grounding`/.test(l)) ?? "";
  84     expect(`grounding row: ${row}`).toContain("Never empty");
  85   });
  86 
  87   test("the example payload carries grounding, so the shape is copyable", () => {
  88     const example = agent.split("```json")[1]?.split("```")[0] ?? "";
  89     expect(example).toContain('"grounding"');
  90   });
  91 
  92   test("the pipeline receives exactly the fields the agent emits", () => {
  93     expect(pipelineFields(pipeline).sort()).toEqual([...declared].sort());
  94   });
  95 
  96   test("chapter 5 documents exactly the fields the agent emits", () => {
  97     expect(chapterFields(chapter).sort()).toEqual([...declared].sort());
  98   });
  99 
 100   test("chapter 5 records that an ungrounded review is discarded, not averaged", () => {
 101     expect(chapter).toContain("discarded rather than averaged");
 102   });
 103 
 104   test.each([
 105     ["empty grounding", "`grounding` is absent or empty"],
 106     ["unparseable report", "not parseable as the JSON contract"],
 107     ["no-tool-use contradiction", "reported no tool use"],
 108   ])("the pipeline names the %s discard condition", (_label, needle) => {
 109     expect(pipeline).toContain(needle);
 110   });
 111 
 112   test("the pipeline discards rather than averages", () => {
 113     const [, screen = ""] = pipeline.split("Discard an ungrounded review");
 114     expect(screen).toContain("Name every discard");
 115     expect(screen).toContain("never silently shrink the panel");
 116   });
 117 
 118   test("a shrunken panel is not reported as a consensus", () => {
 119     expect(pipeline).toContain("single surviving reviewer is a single opinion");
 120     expect(pipeline).toContain("report that the plan is unreviewed");
 121   });
 122 
 123   /**
 124    * The recorded score line names each reviewer's weakest dimension because the scores
 125    * alone say how good the panel thought the plan was, not what to double-check when
 126    * executing it — and nothing reconstructs that later.
 127    */
 128   test("the recorded score line carries the weakest dimension", () => {
 129     expect(pipeline).toContain("weakest:");
 130     expect(pipeline).toContain("weakest dimension");
 131   });
 132 
 133   /**
 134    * The dimension rubric is the sole scoring interface: `score` is the sum of the five
 135    * dimensions, not a second independently judged number. Without this pin the agent
 136    * once carried both a 0-100 prose-band rubric and the dimensions, with the relation
 137    * unstated — a score of 92 over dimensions summing to 88 was schema-valid.
 138    */
 139   test("score is derived from the dimensions, not independently judged", () => {
 140     const row = agent.split("\n").find((l) => /^\|\s*`score`/.test(l)) ?? "";
 141     expect(`score row: ${row}`).toContain("sum of the five `dimensions`");
 142   });
 143 
 144   test("the prose score bands stay deleted — the dimension rubric carries the meaning", () => {
 145     expect(agent).not.toContain("95-100");
 146   });
 147 
 148   test("the retired revision.rescore field stays retired", () => {
 149     expect(agent).not.toContain("rescore");
 150     expect(pipeline).not.toContain("rescore");
 151   });
 152 
 153   test("the pipeline records per-reviewer verdicts rather than averaging them", () => {
 154     expect(pipeline).toContain("no cross-reviewer averaging");
 155   });
 156 
 157   test("the review step gates nothing", () => {
 158     expect(pipeline).toContain("never a gate");
 159     expect(pipeline).not.toContain("Scoring target");
 160     expect(pipeline).not.toMatch(/at most \w+ passes/);
 161   });
 162 
 163   test("chapter 5 documents the same recorded score line", () => {
 164     expect(chapter).toContain("weakest dimension");
 165   });
 166 
 167   test("the agent still forbids asserting unread file contents", () => {
 168     expect(agent).toContain("an inferred file listing is a fabrication");
 169     expect(agent).toContain("Do not list a file you did not open");
 170   });
 171 });
=================== .github/actions/code-review-action/src/linearPlanContract.test.ts
   1 /**
   2  * Guards the contract between `linear-plan`, which stores an implementation plan in a
   3  * Linear issue's description, and `linear-run`, which executes a valid stored plan
   4  * verbatim or falls back to a run-local fresh plan when the artifact is unusable.
   5  *
   6  * Seven properties are load-bearing, and each fails silently without a guard:
   7  *
   8  * 1. The stored-plan section names `linear-run` reads match the ones `linear-plan` writes.
   9  *    This is the real rot: the two files have no import between them, so renaming a
  10  *    section in the producer breaks the consumer with nothing failing in between.
  11  * 2. `linear-run` enumerates every validation verdict and maps it to an execution mode.
  12  *    A verdict quietly dropped can turn an unusable artifact into executable instructions.
  13  * 3. `linear-run` never dispatches `linear-plan` or rewrites the ticket. Its fresh-plan
  14  *    path must remain a run-local fallback rather than silently replacing the artifact.
  15  * 4. The two skills agree on the stored format version. `Format:` is the only thing that
  16  *    keeps "written under an older template" apart from "corrupt", and a version the
  17  *    producer writes but the consumer does not read collapses that distinction.
  18  * 5. Expert review is an enhancement, never a gate. The pipeline states no scoring
  19  *    threshold and no revision budget, and `linear-plan` stores unconditionally with
  20  *    no plan-mode transition — a re-introduced gate would silently start losing plans.
  21  * 6. Expert review is opt-in for `plan` and `linear-plan` alone. The pipeline names them
  22  *    as the only callers that may skip the step and records one literal skipped score
  23  *    line; the `--experts-review` flag lives in those two skills and nowhere else, so
  24  *    the `run` family cannot quietly grow the skip — and a skipped store must stay
  25  *    visible, so `linear-plan` pins the `Score: skipped` stored-header variant.
  26  * 7. `run` stores its finalized plan on the source Linear issue — for `linear-issue`
  27  *    inputs only — by reference to `linear-plan`'s store, inside Phase 4 and before
  28  *    implementation, and a failed write never blocks delivery. The reference link is
  29  *    the sole guard for preserving the prior ticket description: `run` carries no
  30  *    second emission template, so the write contract stays single-source in the
  31  *    producer, and the reader keeps ignoring the `Stored by` attribution — the one
  32  *    field the two producers differ on.
  33  *
  34  * The section names are extracted from the producer's own text rather than hardcoded,
  35  * so the guard tracks the source instead of a copy of it.
  36  *
  37  * What this CANNOT prove: that the gate runs, or that the model honours it. CI sees text
  38  * in a file, nothing more — the same limit `sharedRulesInvocation.test.ts` states for its
  39  * own presence checks. Worse here, no workflow executes this test at all (nothing under
  40  * `.github/workflows/` runs `bun test`), so it gates locally and in review, not in CI.
  41  * Runtime evidence comes from the dry-run recorded on the PR.
  42  */
  43 import { readFile } from "node:fs/promises";
  44 import { join } from "node:path";
  45 
  46 import { describe, expect, test } from "bun:test";
  47 
  48 const actionDir = join(import.meta.dirname, "..");
  49 const repoRoot = join(actionDir, "..", "..", "..");
  50 const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");
  51 
  52 const readSkill = (name: string): Promise<string> =>
  53   readFile(join(skillsDir, name, "SKILL.md"), "utf8");
  54 
  55 const [linearPlan, linearRun, plan, run, runPrimed, pipeline] = await Promise.all([
  56   readSkill("linear-plan"),
  57   readSkill("linear-run"),
  58   readSkill("plan"),
  59   readSkill("run"),
  60   readSkill("run-primed"),
  61   readFile(join(skillsDir, "plan/references/pipeline.md"), "utf8"),
  62 ]);
  63 
  64 /** Every verdict `linear-run`'s validation table must name, fallback ones first. */
  65 const fallbackVerdicts = ["missing", "version-mismatch", "malformed", "unverifiable"];
  66 const allVerdicts = [...fallbackVerdicts, "valid"];
  67 
  68 /**
  69  * `### <name>` rows of the stored-plan template in `linear-plan`, split by its own
  70  * required/caller-owned marker. Reading the producer's template is what makes a renamed
  71  * section fail here rather than at runtime against a live ticket.
  72  */
  73 function storedSections(source: string, kind: "required" | "caller-owned"): string[] {
  74   const rows = source.matchAll(/^###\s+(.+?)\s+<-\s+(required|caller-owned)$/gm);
  75   return [...rows].filter((row) => row[2] === kind).map((row) => row[1].trim());
  76 }
  77 
  78 const requiredSections = storedSections(linearPlan, "required");
  79 const callerOwnedSections = storedSections(linearPlan, "caller-owned");
  80 
  81 /**
  82  * The fenced emission template in `linear-plan` — the literal block the store writes,
  83  * as opposed to the annotated marker list the sections above are parsed from. Pinning
  84  * it keeps the emitted bytes (anchor, header line, section order) from drifting away
  85  * from the contract, and keeps contract annotations from leaking into a live ticket.
  86  */
  87 const emissionTemplate =
  88   linearPlan.match(/### The emission template.*?```text\n(.*?)```/s)?.[1] ?? "";
  89 
  90 /**
  91  * The literal first-store wrapper — the `+++ Original task +++` collapsible the prior
  92  * description moves into. Pinned so the cut around preserved user text stays a fixed
  93  * emission form, mirroring the `+++ Original prompt +++` preamble in `linear-create`.
  94  */
  95 const originalTaskWrapper = linearPlan.match(/```text\n(\+\+\+ Original task\n.*?)```/s)?.[1] ?? "";
  96 
  97 /** The `Source | Section` table rows in `linear-run`, keyed by the source cell. */
  98 function sectionTableRow(source: string, key: string): string {
  99   const row = source
 100     .split("\n")
 101     .map((line) => line.split("|").map((cell) => cell.trim()))
 102     .find((cells) => cells.length > 2 && cells[1] === key);
 103   return row ? row[2] : "";
 104 }
 105 
 106 describe("linear plan contract", () => {
 107   test("the stored-plan template still exposes a required/caller-owned split", () => {
 108     expect(requiredSections.length).toBeGreaterThan(1);
 109     expect(callerOwnedSections.length).toBeGreaterThan(0);
 110   });
 111 
 112   test.each(allVerdicts)("linear-run names the %s verdict", (verdict) => {
 113     expect(linearRun).toContain(`**${verdict}**`);
 114   });
 115 
 116   test.each(fallbackVerdicts)("the %s verdict selects a fresh plan", (verdict) => {
 117     const message = linearRun.split("\n").find((line) => line.startsWith(`- ${verdict} —`));
 118     expect(`${verdict}: ${message ?? "<no message line>"}`).toContain(
 119       "drafting a fresh implementation plan",
 120     );
 121   });
 122 
 123   test("the verdict table maps valid to stored-plan and every other verdict to fresh-plan", () => {
 124     const validRow = linearRun
 125       .split("\n")
 126       .find((line) => line.includes("| **valid**") && line.includes("`stored-plan`"));
 127     const fallbackRow = linearRun
 128       .split("\n")
 129       .find(
 130         (line) =>
 131           line.includes("`fresh-plan`") &&
 132           fallbackVerdicts.every((verdict) => line.includes(`**${verdict}**`)),
 133       );
 134     expect(validRow).toContain("`stored-plan`");
 135     expect(fallbackRow).toContain("`fresh-plan`");
 136   });
 137 
 138   test("linear-run never invokes the producer or overwrites the stored artifact", () => {
 139     expect(linearRun).not.toContain("Skill(autopilot:linear-plan)");
 140     expect(linearRun).toContain("never writes or repairs a stored plan");
 141     expect(linearRun).toContain("Do not store it on the Linear issue");
 142   });
 143 
 144   test.each([
 145     ["admission", "Only the Linear issue is required"],
 146     ["snapshot", "The plan is a snapshot, not a live view"],
 147   ])("linear-run states the %s contract", (_label, needle) => {
 148     expect(linearRun).toContain(needle);
 149   });
 150 
 151   test("linear-run uses the shared planning pipeline for its fresh-plan path", () => {
 152     expect(linearRun).toContain("[pipeline.md](../plan/references/pipeline.md)");
 153     // Pipeline phases map to this skill's tasks by subject, not by index —
 154     // index-based references broke whenever either side inserted a phase.
 155     expect(linearRun).toContain("Establish-plan task");
 156     expect(linearRun).toContain("Validate-plan task");
 157     expect(linearRun).toContain("Finalize-plan task");
 158   });
 159 
 160   test.each(requiredSections)("linear-run consumes `### %s` from the stored plan", (name) => {
 161     expect(sectionTableRow(linearRun, "Stored plan")).toContain(`\`### ${name}\``);
 162   });
 163 
 164   test.each(callerOwnedSections)("`### %s` is stored but explicitly not consumed", (name) => {
 165     expect(sectionTableRow(linearRun, "Stored plan, **unused**")).toContain(`\`### ${name}\``);
 166     expect(sectionTableRow(linearRun, "Stored plan")).not.toContain(`\`### ${name}\``);
 167   });
 168 
 169   test("both skills agree on the stored format version", () => {
 170     const written = linearPlan.match(/Format:\s*(v\d+)/)?.[1];
 171     expect(written).toBeTruthy();
 172     expect(linearRun).toContain(`\`${written}\``);
 173   });
 174 
 175   test("the pipeline states no scoring threshold and no revision budget", () => {
 176     expect(pipeline).not.toContain("Scoring target");
 177     expect(pipeline).not.toMatch(/at most \w+ passes/);
 178     expect(pipeline).toContain("not a gate for any caller");
 179   });
 180 
 181   test("linear-plan stores unconditionally, with no plan-mode transition", () => {
 182     expect(linearPlan).toContain("Storing is unconditional");
 183     expect(linearPlan).toContain("Do not add a separate approval step");
 184     expect(linearPlan).not.toContain("ExitPlanMode");
 185     expect(linearPlan).not.toContain("EnterPlanMode");
 186     expect(linearPlan).not.toContain("Decide whether to store");
 187   });
 188 
 189   /**
 190    * The title refresh is part of the store contract (issue #578: a rewording once dropped
 191    * it silently). Pin its source, its rules link, and that both outcome literals appear
 192    * twice — once in the write step and once in the final output block.
 193    */
 194   test("the store refreshes the title from the plan and reports the outcome", () => {
 195     const writeSection = linearPlan.split("### The write")[1] ?? "";
 196     expect(writeSection).toContain("**Derive the title.**");
 197     expect(writeSection).toContain("Steelmanned Intent");
 198     expect(writeSection).toContain("../linear-create/SKILL.md#phase-2-generate-title-and-body");
 199     expect(writeSection).toContain("needs no confirmation");
 200     expect(linearPlan.match(/✓ Title updated: <new title>/g)?.length ?? 0).toBeGreaterThanOrEqual(
 201       2,
 202     );
 203     expect(linearPlan.match(/`title unchanged`/g)?.length ?? 0).toBeGreaterThanOrEqual(2);
 204   });
 205 
 206   test("linear-run treats the stored plan as a durable artifact, not proof of approval", () => {
 207     expect(linearRun).toContain("checkable durable artifact");
 208     expect(linearRun).not.toContain("approval already happened when the plan was stored");
 209     expect(linearRun).not.toContain("plan somebody approved");
 210   });
 211 
 212   test.each([
 213     ["revision", "Stored plan was drafted against"],
 214     ["path", "path(s) that no longer exist"],
 215   ])("linear-run reports %s drift", (_label, needle) => {
 216     expect(linearRun).toContain(needle);
 217   });
 218 
 219   test("both drift reports stay advisory rather than becoming verdicts", () => {
 220     const [, drift = ""] = linearRun.split("report how far the plan has aged");
 221     expect(drift).toContain("advisory and never a verdict");
 222     // A drift report must not be smuggled in as a sixth plan-source verdict.
 223     for (const verdict of fallbackVerdicts) {
 224       expect(`drift section names ${verdict}: ${drift.includes(`**${verdict}**`)}`).toBe(
 225         `drift section names ${verdict}: false`,
 226       );
 227     }
 228   });
 229 
 230   /**
 231    * Both carve-outs guard the same failure: the plan template stores an existing file as
 232    * `path/to/file.ts:NN` and a planned one with a `(new)` suffix, so a literal existence
 233    * test on the raw entry reports every file as missing — the cry-wolf outcome that would
 234    * make the report worthless.
 235    */
 236   test.each([
 237     ["files it intends to create", "absent by design"],
 238     ["a trailing line number", "Strip a trailing"],
 239   ])("the path check handles %s", (_label, needle) => {
 240     const [, drift = ""] = linearRun.split("**Path drift.**");
 241     expect(drift).toContain(needle);
 242   });
 243 
 244   test("the pipeline gates the review step on plan and linear-plan alone", () => {
 245     expect(pipeline).toContain("the only callers that may skip");
 246     expect(pipeline).toContain(
 247       "Score: skipped · expert review disabled (invoked without --experts-review)",
 248     );
 249   });
 250 
 251   test.each([
 252     ["plan", plan],
 253     ["linear-plan", linearPlan],
 254   ])("%s's argument-hint carries the --experts-review flag", (_name, source) => {
 255     expect(source).toMatch(/argument-hint:.*--experts-review/);
 256   });
