 189   /**
 190    * The title refresh is part of the store contract (issue #578: a rewording once dropped
 191    * it silently). Pin its source, its rules link, and that both outcome literals appear
 192    * twice — once in the write step and once in the final output block.
 193    */
 194   test("the store refreshes the title from the plan and reports the outcome", () => {
 195     const writeSection = linearPlan.split("### The write")[1] ?? "";
